package info.openrocket.core.aerodynamics.physicsaero.thermodynamics;
public final class HighMachThermodynamicSelector {public enum Model{PERFECT_GAS,THERMALLY_PERFECT_FROZEN,EQUILIBRIUM_AIR,INVALID_IONIZATION}public record Selection(Model model,double stagnationTemperatureK,String reason){}public Selection select(double mach,double staticTemperature,double velocity){if(mach<5)return new Selection(Model.PERFECT_GAS,staticTemperature,"BELOW_HIGH_MACH_HANDOFF");double tt=new ThermallyPerfectAir().totalTemperature(staticTemperature,velocity);if(tt>6000)return new Selection(Model.INVALID_IONIZATION,tt,"NASA_POLYNOMIAL_OR_IONIZATION_LIMIT");return new Selection(tt<2500?Model.THERMALLY_PERFECT_FROZEN:Model.EQUILIBRIUM_AIR,tt,tt<2500?"CALORICALLY_IMPERFECT_FROZEN":"EQUILIBRIUM_FIVE_SPECIES");}}
